fn is_greater(n: i32, a: &Vec<i32>) -> bool {
    // Return true iff n is strictly greater than every element in a.
    a.iter().all(|&x| n > x)
}

fn main() {
    // Example usage / quick sanity checks
    let a = vec![1, 2, 3];
    assert!(is_greater(4, &a));
    assert!(!is_greater(3, &a)); // not strictly greater than 3
    assert!(!is_greater(2, &a)); // not greater than 2 or 3

    let b = vec![-10, -20];
    assert!(is_greater(-5, &b));
    assert!(!is_greater(-10, &b)); // equal to an element
}